package com.bank.loan;

import java.util.Arrays;
import java.util.logging.Logger;

public class DuplicateDemo {
    private static final Logger log = Logger.getLogger(DuplicateDemo.class.getName());

    public static void main(String[] args) {
        int[] feed = {1, 3, 4, 2, 2};   // n=4, n+1=5 records, 2 repeats
        log.info("Loan application numbers: " + Arrays.toString(feed));

        LoanDuplicateDetector detector = new LoanDuplicateDetector();

        int viaFloyd = detector.findDuplicateFloyd(feed.clone()); // read-only variant
        log.info("Duplicate via Floyd (array untouched): " + viaFloyd);

        int viaCyclic = detector.findDuplicateCyclic(feed.clone()); // mutating variant
        log.info("Duplicate via Cyclic Sort: " + viaCyclic);
    }
}
