package com.bank.loan;

public class LoanDuplicateDetector {

    // Read-only: treat values as next-pointers, find cycle entry (the duplicate).
    public int findDuplicateFloyd(int[] nums) {
        int slow = nums[0], fast = nums[0];
        do {
            slow = nums[slow];
            fast = nums[nums[fast]];
        } while (slow != fast);           // meet inside the cycle
        slow = nums[0];
        while (slow != fast) {            // walk both at equal speed to the entry
            slow = nums[slow];
            fast = nums[fast];
        }
        return slow;                      // cycle entrance = duplicate
    }

    // Mutating: cyclic placement, return the first value already at its home.
    public int findDuplicateCyclic(int[] nums) {
        int i = 0;
        while (i < nums.length) {
            if (nums[i] != i + 1) {
                int target = nums[i] - 1;
                if (nums[i] != nums[target]) {
                    int tmp = nums[i]; nums[i] = nums[target]; nums[target] = tmp;
                } else {
                    return nums[i];       // home already holds this value → duplicate
                }
            } else {
                i++;
            }
        }
        return -1;
    }
}
